import request from 'supertest';
import { describe, it, expect, beforeEach } from 'vitest';
import { createApp } from '../../src/app.js';
import usersRoutes from '../../src/routes/users.js';

describe('Users API', () => {
  let app: any;
  let baseUrl = '/v1/users';

  beforeEach(() => {
    app = createApp(usersRoutes());
  });

  describe('POST /v1/users - Create user', () => {
    it('should create a user with valid email and name', async () => {
      const res = await request(app)
        .post(baseUrl)
        .send({ email: 'alice@example.com', name: 'Alice' });

      expect(res.status).toBe(201);
      expect(res.body.id).toBeDefined();
      expect(res.body.email).toBe('alice@example.com');
      expect(res.body.name).toBe('Alice');
      expect(res.body.createdAt).toBeDefined();
      expect(res.headers.location).toBe(`/v1/users/${res.body.id}`);
    });

    it('should reject duplicate email with 409', async () => {
      await request(app)
        .post(baseUrl)
        .send({ email: 'bob@example.com', name: 'Bob' });

      const res = await request(app)
        .post(baseUrl)
        .send({ email: 'bob@example.com', name: 'Bob Again' });

      expect(res.status).toBe(409);
    });

    it('should reject missing email with 422', async () => {
      const res = await request(app)
        .post(baseUrl)
        .send({ name: 'NoEmail' });

      expect(res.status).toBe(422);
    });

    it('should reject invalid email with 422', async () => {
      const res = await request(app)
        .post(baseUrl)
        .send({ email: 'not-an-email', name: 'Invalid' });

      expect(res.status).toBe(422);
    });

    it('should reject missing name with 422', async () => {
      const res = await request(app)
        .post(baseUrl)
        .send({ email: 'test@example.com' });

      expect(res.status).toBe(422);
    });

    it('should reject empty name with 422', async () => {
      const res = await request(app)
        .post(baseUrl)
        .send({ email: 'test@example.com', name: '' });

      expect(res.status).toBe(422);
    });

    it('should reject name > 100 chars with 422', async () => {
      const res = await request(app)
        .post(baseUrl)
        .send({ email: 'test@example.com', name: 'a'.repeat(101) });

      expect(res.status).toBe(422);
    });
  });

  describe('GET /v1/users/:id - Get user', () => {
    it('should get a user by id', async () => {
      const createRes = await request(app)
        .post(baseUrl)
        .send({ email: 'charlie@example.com', name: 'Charlie' });

      const id = createRes.body.id;

      const res = await request(app).get(`${baseUrl}/${id}`);

      expect(res.status).toBe(200);
      expect(res.body.id).toBe(id);
      expect(res.body.email).toBe('charlie@example.com');
      expect(res.body.name).toBe('Charlie');
    });

    it('should return 404 for unknown id', async () => {
      const res = await request(app).get(`${baseUrl}/00000000-0000-0000-0000-000000000000`);

      expect(res.status).toBe(404);
    });
  });

  describe('GET /v1/users - List users', () => {
    it('should list users with default limit', async () => {
      await request(app)
        .post(baseUrl)
        .send({ email: 'user1@example.com', name: 'User 1' });
      await request(app)
        .post(baseUrl)
        .send({ email: 'user2@example.com', name: 'User 2' });

      const res = await request(app).get(baseUrl);

      expect(res.status).toBe(200);
      expect(res.body.data).toHaveLength(2);
      expect(res.body.data[0].email).toBe('user1@example.com');
    });

    it('should support cursor pagination with limit', async () => {
      for (let i = 0; i < 5; i++) {
        await request(app)
          .post(baseUrl)
          .send({ email: `user${i}@example.com`, name: `User ${i}` });
      }

      const res1 = await request(app).get(baseUrl).query({ limit: 2 });

      expect(res1.status).toBe(200);
      expect(res1.body.data).toHaveLength(2);
      expect(res1.body.nextCursor).toBeDefined();

      const res2 = await request(app)
        .get(baseUrl)
        .query({ limit: 2, cursor: res1.body.nextCursor });

      expect(res2.status).toBe(200);
      expect(res2.body.data).toHaveLength(2);
    });

    it('should reject limit > 100 with 422', async () => {
      const res = await request(app).get(baseUrl).query({ limit: 101 });

      expect(res.status).toBe(422);
    });

    it('should return empty list', async () => {
      const res = await request(app).get(baseUrl);

      expect(res.status).toBe(200);
      expect(res.body.data).toHaveLength(0);
    });
  });

  describe('PATCH /v1/users/:id - Update user', () => {
    it('should update user email', async () => {
      const createRes = await request(app)
        .post(baseUrl)
        .send({ email: 'dave@example.com', name: 'Dave' });

      const id = createRes.body.id;

      const res = await request(app)
        .patch(`${baseUrl}/${id}`)
        .send({ email: 'dave.new@example.com' });

      expect(res.status).toBe(200);
      expect(res.body.id).toBe(id);
      expect(res.body.email).toBe('dave.new@example.com');
      expect(res.body.name).toBe('Dave');
    });

    it('should update user name', async () => {
      const createRes = await request(app)
        .post(baseUrl)
        .send({ email: 'eve@example.com', name: 'Eve' });

      const id = createRes.body.id;

      const res = await request(app)
        .patch(`${baseUrl}/${id}`)
        .send({ name: 'Evangeline' });

      expect(res.status).toBe(200);
      expect(res.body.email).toBe('eve@example.com');
      expect(res.body.name).toBe('Evangeline');
    });

    it('should reject duplicate email with 409', async () => {
      await request(app)
        .post(baseUrl)
        .send({ email: 'frank@example.com', name: 'Frank' });
      const user2 = await request(app)
        .post(baseUrl)
        .send({ email: 'grace@example.com', name: 'Grace' });

      const res = await request(app)
        .patch(`${baseUrl}/${user2.body.id}`)
        .send({ email: 'frank@example.com' });

      expect(res.status).toBe(409);
    });

    it('should return 404 for unknown id', async () => {
      const res = await request(app)
        .patch(`${baseUrl}/00000000-0000-0000-0000-000000000000`)
        .send({ name: 'Unknown' });

      expect(res.status).toBe(404);
    });

    it('should reject invalid email with 422', async () => {
      const createRes = await request(app)
        .post(baseUrl)
        .send({ email: 'hank@example.com', name: 'Hank' });

      const res = await request(app)
        .patch(`${baseUrl}/${createRes.body.id}`)
        .send({ email: 'not-an-email' });

      expect(res.status).toBe(422);
    });

    it('should reject empty name with 422', async () => {
      const createRes = await request(app)
        .post(baseUrl)
        .send({ email: 'iris@example.com', name: 'Iris' });

      const res = await request(app)
        .patch(`${baseUrl}/${createRes.body.id}`)
        .send({ name: '' });

      expect(res.status).toBe(422);
    });

    it('should reject name > 100 chars with 422', async () => {
      const createRes = await request(app)
        .post(baseUrl)
        .send({ email: 'jack@example.com', name: 'Jack' });

      const res = await request(app)
        .patch(`${baseUrl}/${createRes.body.id}`)
        .send({ name: 'a'.repeat(101) });

      expect(res.status).toBe(422);
    });
  });

  describe('DELETE /v1/users/:id - Delete user', () => {
    it('should delete a user', async () => {
      const createRes = await request(app)
        .post(baseUrl)
        .send({ email: 'karen@example.com', name: 'Karen' });

      const id = createRes.body.id;

      const deleteRes = await request(app).delete(`${baseUrl}/${id}`);

      expect(deleteRes.status).toBe(204);
      expect(deleteRes.body).toEqual({});

      const getRes = await request(app).get(`${baseUrl}/${id}`);
      expect(getRes.status).toBe(404);
    });

    it('should return 404 for unknown id', async () => {
      const res = await request(app).delete(`${baseUrl}/00000000-0000-0000-0000-000000000000`);

      expect(res.status).toBe(404);
    });
  });
});
